package com.campusnova.service;
import com.campusnova.dto.ChatRequest; import com.campusnova.knowledge.*; import com.campusnova.model.ChatHistory; import com.campusnova.repository.ChatHistoryRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class NovaChatService { private final ConversationService conversations; private final KnowledgeRetrievalService retrieval; private final CollegeRelevanceService relevance; private final BedrockService bedrock; private final GroundingValidationService grounding; private final ChatHistoryRepository history; public NovaChatService(ConversationService c,KnowledgeRetrievalService r,CollegeRelevanceService rel,BedrockService b,GroundingValidationService g,ChatHistoryRepository h){conversations=c;retrieval=r;relevance=rel;bedrock=b;grounding=g;history=h;}
 public Map<String,Object> respond(ChatRequest request){long start=System.currentTimeMillis();String question=request.getQuestion().trim();String session=request.getSessionId()==null||request.getSessionId().trim().isEmpty()?"guest":request.getSessionId();List<String> memory=conversations.recentTerms(session);RetrievalResult found=retrieval.retrieve(question,memory);boolean college=relevance.isCollegeRelated(question,found,memory);String answer,type,category="General";boolean answered=false;if(!college){answer="I’m NOVA, CampusNova’s college AI assistant. I can help with college information such as courses, fees, admissions, exams, facilities, placements, or campus services.";type="OUT_OF_DOMAIN";}else if(found.getConfidence()>=.55&&!found.getDocuments().isEmpty()){KnowledgeDocument doc=found.getDocuments().get(0);answer=directAnswer(doc);category=doc.getCategory();answered=true;type="DIRECT_FAQ";}else if(found.hasContext()){Optional<String> generated=bedrock.generate(question,found);if(generated.isPresent()&&grounding.acceptable(generated.get(),found)){answer=generated.get();type="AI_RAG";answered=true;category=found.getDocuments().get(0).getCategory();}else{answer=groundedSummary(found);type="RETRIEVAL_FALLBACK";answered=true;category=found.getDocuments().get(0).getCategory();}}else{answer="That appears to be a college-related question, but the information is not currently available in the CampusNova knowledge base. Please check the relevant department, college office, official notice, or faculty coordinator for a verified answer.";type="KNOWLEDGE_GAP";}long elapsed=System.currentTimeMillis()-start;history.save(new ChatHistory(session,question,answer,category,answered,type,!college,elapsed));Map<String,Object> response=new LinkedHashMap<String,Object>();response.put("answer",answer);response.put("category",category);response.put("answered",answered);response.put("responseType",type);response.put("sources",found.sources());response.put("suggestions",Arrays.asList("Ask about admissions","Find library information","Explore placements"));return response; }
 private String directAnswer(KnowledgeDocument document){String[] lines=document.getContent().split("\\n");return lines.length>1?lines[1]:document.getContent();} private String groundedSummary(RetrievalResult found){KnowledgeDocument d=found.getDocuments().get(0);String[] lines=d.getContent().split("\\n");String information=lines.length>1?lines[1]:d.getContent();return information+"\n\nThis response is based on available CampusNova knowledge. Please confirm time-sensitive details through the relevant official channel.";} }
